from optimize import densify,MM,mask,view,targs
from stick_model import render as physical_render
import numpy as np,time
from scipy.ndimage import distance_transform_edt,binary_dilation
P=np.load('/app/output/main_model_params.npy');B=np.load('/app/output/main_before_touchup.npy');SZ=512

def render(path,sz=1024):
 sta=np.tile(path[0],(12,1));sta[:,2]=np.linspace(.01,path[0,2],12)
 end=np.tile(path[-1],(25,1));end[:,2]=np.linspace(path[-1,2],.01,25)
 return physical_render(P,np.r_[sta,path,end],(sz,sz),sz/1024/MM)

def run(i):
 n=np.load(f'/app/output/main_nodes_{i}.npy').copy()
 if i==1:
  # Smooth lengthwise retrace of horizontal, vertical, and the returning hook.
  n=np.array([[350,325,1],[403,337,4],[460,323,6],[527,301,7],[600,274,10],[667,284,10],[688,332,10],[683,400,17],[684,480,17],[688,590,17],[692,686,14],[689,750,14],[650,741,13],[607,682,12],[570,643,8],[530,628,1]],float);n[:,:2]*=MM
 else:
  # The left stem returns into the upper inner loop and descends along its right side.
  n=np.array([[417,474,1],[432,521,3],[445,570,7],[462,627,8],[454,583,3],[452,546,4],[483,510,4],[520,480,4],[555,458,4],[574,484,7],[582,530,12],[563,580,13],[535,625,8],[541,634,1]],float);n[:,:2]*=MM
 initial=n.copy();N=len(n);tar=targs[i][::2,::2];base=B[::2,::2];full=mask[::2,::2];outside=distance_transform_edt(~full)*MM*2
 def loss(a):
  m=render(densify(a),SZ);combined=base|m
  missing=(tar&~combined).sum()
  new=(m&~base);stray=(np.minimum(outside,5)*new).sum()
  dd=np.diff(a[:,:2],axis=0);dd/=np.maximum(.01,np.linalg.norm(dd,axis=1))[:,None];bend=((np.diff(dd,axis=0))**2).sum()
  return missing+4*stray/(MM*2)+40*bend
 best=loss(n);rng=np.random.default_rng(46);print('start',i,best,flush=True)
 for rnd,step in enumerate([3,2,1,.6,.35]):
  change=0;t=time.time()
  for rep in range(3):
   for block in [3,1]:
    for j in rng.permutation(N):
     for k in rng.permutation(3):
      for sign in rng.permutation([-1,1]):
       a=n.copy();lo=max(0,j-block//2);hi=min(N,j+block//2+1);a[lo:hi,k]+=sign*step*(.7 if k==2 else 1);a[:,2]=np.clip(a[:,2],.65,20)
       if a[0,2]>2 or a[-1,2]>2:continue
       if np.max(np.linalg.norm(a[:,:2]-initial[:,:2],axis=1))>9:continue
       if i==1:
        if np.any(np.diff(a[:7,0])<0) or np.any(np.diff(a[6:12,1])<0) or np.any(np.diff(a[11:,0])>0):continue
        if np.any(a[6:11,0]<670*MM) or np.any(a[6:11,0]>706*MM):continue
       val=loss(a)
       if val<best-1e-5:best=val;n=a;change+=1
  print('round',i,rnd,best,change,round(time.time()-t,1),flush=True)
  np.save(f'/app/output/touchup_nodes_{i}.npy',n);view(B|render(densify(n)),f'/app/output/touchup_plan_{i}.png')
 return n
if __name__=='__main__':
 for i in [1,3]:run(i)
 ss=[densify(np.load(f'/app/output/touchup_nodes_{i}.npy')) for i in [1,3]];m=B|render(ss[0])|render(ss[1]);view(m,'/app/output/touchup_plan.png');print('predicted union iou',(m&mask).sum()/(m|mask).sum(),'coverage',(m&mask).sum()/mask.sum(),flush=True)
PY
